import{_ as t,c as a,o as n,a3 as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Finance","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/index.md","filePath":"master/finance/index.md","lastUpdated":1792041590000}'),r={name:"master/finance/index.md"};function i(s,e,c,l,d,h){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="finance" tabindex="-1">Finance <a class="header-anchor" href="#finance" aria-label="Permalink to &quot;Finance&quot;">​</a></h1><p>The finance side of Aureus covers everything about money: billing customers, paying vendors, recording payments, keeping the books and reading financial reports. Two apps share this work. The <strong>Invoices</strong> app is a simple tool for day-to-day billing. The <strong>Accounting</strong> app adds the full books and reports on top.</p><blockquote><p><strong>In simple words:</strong> Invoices is for billing and paying. Accounting is for billing, paying and seeing the full books.</p></blockquote><h2 id="the-two-apps" tabindex="-1">The two apps <a class="header-anchor" href="#the-two-apps" aria-label="Permalink to &quot;The two apps&quot;">​</a></h2><p>Both apps work on the same data. An invoice made in one app shows up in the other.</p><ul><li><strong>Invoices app:</strong> Create invoices, credit notes, bills, refunds and payments. Set up taxes, payment terms and bank accounts.</li><li><strong>Accounting app:</strong> Does everything the Invoices app does. It also gives you accounting entries, the chart of accounts, journals and financial reports.</li></ul><p>The invoice, credit note, bill, refund and payment screens are identical in both apps. Only the menu path changes. For example, use <code>Invoices → Customers → Invoices</code> or <code>Accounting → Customers → Invoices</code>.</p><h3 id="only-in-the-accounting-app" tabindex="-1">Only in the Accounting app <a class="header-anchor" href="#only-in-the-accounting-app" aria-label="Permalink to &quot;Only in the Accounting app&quot;">​</a></h3><ul><li><strong>Overview:</strong> A dashboard with one card for each journal.</li><li><strong>Journal Entries</strong> and <strong>Journal Items:</strong> The accounting records behind every document.</li><li><strong>Reporting:</strong> Balance Sheet, Profit &amp; Loss, General Ledger, Trial Balance, Partner Ledger, Aged Receivable and Aged Payable.</li><li><strong>Chart of Accounts</strong>, <strong>Journals</strong> and <strong>Fiscal Positions</strong>.</li><li><strong>Settings:</strong> Manage Taxes, Manage Customer Invoice and Manage Default Accounts, plus Manage Products with <strong>Variants</strong>.</li></ul><h3 id="only-in-the-invoices-app" tabindex="-1">Only in the Invoices app <a class="header-anchor" href="#only-in-the-invoices-app" aria-label="Permalink to &quot;Only in the Invoices app&quot;">​</a></h3><ul><li>The <strong>Bank Accounts</strong> menu item under <strong>Configurations</strong>.</li><li>A <strong>Settings</strong> page with one option: <strong>Unit of Measure</strong>.</li></ul><h2 id="which-app-should-i-use" tabindex="-1">Which app should I use? <a class="header-anchor" href="#which-app-should-i-use" aria-label="Permalink to &quot;Which app should I use?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to</th><th>Use</th></tr></thead><tbody><tr><td>Send invoices and record bills and payments</td><td>Either app</td></tr><tr><td>Keep a product list with taxes</td><td>Either app</td></tr><tr><td>See journal entries and journal items</td><td>Accounting</td></tr><tr><td>Read a balance sheet or profit and loss report</td><td>Accounting</td></tr><tr><td>Set up the chart of accounts and journals</td><td>Accounting</td></tr><tr><td>Map taxes and accounts by customer location</td><td>Accounting (Fiscal Positions)</td></tr><tr><td>Keep things simple, with no books</td><td>Invoices</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you run the Accounting app, you do not need the Invoices app. Every billing screen is already in Accounting.</p></div><h2 id="how-the-money-flows" tabindex="-1">How the money flows <a class="header-anchor" href="#how-the-money-flows" aria-label="Permalink to &quot;How the money flows&quot;">​</a></h2><p>Here is a simple example from start to finish.</p><ol><li>You sell goods to a customer called Azure Interiors. You create a customer invoice and click <strong>Confirm</strong>. See <a href="./customer-invoices/create-invoice.html">Create an invoice</a>.</li><li>The customer pays. You click <strong>Pay</strong> on the invoice and register the payment. See <a href="./payments/register-payment.html">Register a payment</a>.</li><li>The invoice moves from <strong>Not paid</strong> to <strong>Paid</strong>.</li><li>In Accounting, each step writes lines in the books. Confirming the invoice records what the customer owes you and your income. The payment records the money received. See <a href="./accounting-entries/journal-entries.html">Journal entries</a>.</li><li>The reports read those lines. The invoice raises your income in <strong>Profit &amp; Loss</strong>. The unpaid amount shows in <strong>Aged Receivable</strong>. See <a href="./reporting/">Reporting</a>.</li></ol><p>Buying works the same way in reverse. You record a vendor bill, confirm it, pay it, and the books record the cost.</p><h2 id="groups-in-this-guide" tabindex="-1">Groups in this guide <a class="header-anchor" href="#groups-in-this-guide" aria-label="Permalink to &quot;Groups in this guide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./get-started/">Get started</a></td><td>Set up accounting, the chart of accounts, journals, default accounts and currencies</td></tr><tr><td><a href="./taxes/">Taxes</a></td><td>Taxes, tax groups, fiscal positions and tax settings</td></tr><tr><td><a href="./customer-invoices/">Customer invoices</a></td><td>Invoicing processes, invoices, credit notes and refunds, payment terms, incoterms and invoice numbers</td></tr><tr><td><a href="./vendor-bills/">Vendor bills</a></td><td>Recording a bill, paying it and bill numbers</td></tr><tr><td><a href="./payments/">Payments</a></td><td>Register and manage payments, and bank accounts</td></tr><tr><td><a href="./accounting-entries/">Accounting entries</a></td><td>Journal entries and journal items</td></tr><tr><td><a href="./reporting/">Reporting</a></td><td>Financial reports and their exports</td></tr><tr><td><a href="./configuration/">Configuration</a></td><td>Every settings and configuration page in one list</td></tr></tbody></table><h2 id="set-up-in-this-order" tabindex="-1">Set up in this order <a class="header-anchor" href="#set-up-in-this-order" aria-label="Permalink to &quot;Set up in this order&quot;">​</a></h2><ol><li>Set up accounting for your company. See <a href="./get-started/accounting-setup.html">Accounting setup</a>.</li><li>Review the <a href="./get-started/chart-of-accounts.html">chart of accounts</a> and the <a href="./get-started/journals.html">journals</a>.</li><li>Check the <a href="./get-started/default-accounts.html">default accounts</a>.</li><li>Create your <a href="./taxes/taxes.html">taxes</a> and review <a href="./taxes/tax-settings.html">tax settings</a>.</li><li>Add <a href="./customer-invoices/payment-terms.html">payment terms</a> and <a href="./payments/bank-accounts.html">bank accounts</a>.</li><li>Create your <a href="./../sales/sales/products-prices/manage-products.html">products</a>, <a href="./../sales/sales/quotations-orders/manage-customers.html">customers</a> and <a href="./../getting-started/contacts/contacts.html">vendors</a>.</li><li>Create your first <a href="./customer-invoices/create-invoice.html">invoice</a> or <a href="./vendor-bills/create-bill.html">bill</a>.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./get-started/">Get started</a></li><li><a href="./configuration/">Configuration</a></li><li><a href="./../sales/sales/">Sales overview</a></li></ul>',24)]))}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
